{
  "role": "structure",
  "inspection_scope": "Complete supplied script, film_structure, setup s1 and beat b1 shot contract; data-only review before animation.",
  "checks": [
    {
      "check": "METAPHOR_OVERLOAD",
      "status": "PASS",
      "evidence": "s1 uses one physical rule: closing a route gap permits the blocked token to cross."
    },
    {
      "check": "STATE_ACCUMULATION_WITHOUT_MEANING",
      "status": "PASS",
      "evidence": "b1 replaces the blocked-route state with a closed bridge and completed crossing; no obsolete mechanism is retained."
    },
    {
      "check": "SEMANTIC_GROUP_OVERLOAD",
      "status": "PASS",
      "evidence": "The route, bridge and token form one causal transit group."
    },
    {
      "check": "COMPOSITIONAL_STAGNATION",
      "status": "PASS",
      "evidence": "There is one proposition and one close-cropped setup; no unrelated propositions repeat its staging."
    },
    {
      "check": "CONTINUITY_TOKEN_OVERLOAD",
      "status": "PASS",
      "evidence": "No tokens persist across setups. The local token has a meaningful lifecycle from blocked at the gap to carried across the closed bridge."
    },
    {
      "check": "CLUTTER_WITHOUT_PURPOSE",
      "status": "PASS",
      "evidence": "The paper backboard and work surface support the physical route stage; the corner crop directs attention to the active contact."
    },
    {
      "check": "WEAK_RESET_RHYTHM",
      "status": "PASS",
      "evidence": "Bridge closure and crossing develop the same rule without a semantic shift; the setup ends with its visible consequence."
    },
    {
      "check": "COMPETING_FOCI",
      "status": "PASS",
      "evidence": "The planned dominant action is localized at the gap: the bridge closes, then the token crosses. No independent secondary action competes."
    },
    {
      "check": "CAPTION_CARRIES_STORY",
      "status": "PASS",
      "evidence": "The blocked token, visible gap, bridge closure and resulting crossing physically express the entire narrated claim."
    }
  ],
  "setup_assessments": [
    {
      "setup_id": "s1",
      "status": "PASS",
      "evidence": "s1 assigns the sole beat once and covers all six narration words. Its shot contract supplies a coherent condition, action and consequence under one transit rule, with an absent Bot and a purposeful minimal environment."
    }
  ],
  "violations": [],
  "limits": "Data-only review cannot establish rendered/mobile performance, final artwork, pixel visibility, animation execution or listening quality."
}
